import re
from collections import defaultdict

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    lines = text.splitlines()

    # Parse the INI file
    sections = {}
    current_section = None
    default_section = {}
    key_lines = []

    for line_num, line in enumerate(lines, 1):
        stripped_line = line.strip()

        # Skip empty lines and comments
        if not stripped_line or stripped_line[0] in ';#':
            continue

        # Check for section header
        if stripped_line.startswith('[') and stripped_line.endswith(']'):
            section_name = stripped_line[1:-1].strip()
            if not section_name:
                raise ValueError(f"Line {line_num}: Empty section name")
            current_section = section_name
            sections[section_name] = {}
            continue

        # If we encounter a key line before any section, raise error
        if current_section is None:
            raise ValueError(f"Line {line_num}: Key value before any section header")

        # Parse key-value pairs
        # Allow both = and : as separators, but only the first one counts
        if '=' in stripped_line:
            sep_pos = stripped_line.find('=')
            key_part = stripped_line[:sep_pos]
            value_part = stripped_line[sep_pos+1:]
        elif ':' in stripped_line:
            sep_pos = stripped_line.find(':')
            key_part = stripped_line[:sep_pos]
            value_part = stripped_line[sep_pos+1:]
        else:
            raise ValueError(f"Line {line_num}: Malformed key-value line")

        key = key_part.strip().lower()
        value = value_part.strip()

        # Check for inline comment
        comment_start = value.find(' ;')
        if comment_start == -1:
            comment_start = value.find(' #')
        if comment_start != -1:
            value = value[:comment_start]

        # Handle quoted values
        if value.startswith('"') and value.endswith('"') and len(value) >= 2:
            value = value[1:-1]  # Remove quotes
        else:
            value = value.strip()

        # Check for continuation
        if key_lines and not key_lines[-1][0] and line.startswith(' '):
            # This is a continuation line
            prev_key, prev_value = key_lines[-1]
            key_lines[-1] = (prev_key, prev_value + '\n' + value.strip())
        else:
            key_lines.append((key, value))
            sections[current_section][key] = value

    # Apply DEFAULT section to other sections
    default_keys = default_section.copy()

    # Handle interpolation
    def interpolate_value(value: str, section_name: str, seen: list = None) -> str:
        if seen is None:
            seen = []
        # Do interpolation
        def replace_match(match):
            if match.group(0) == '$':
                return '$'
            # Extract the reference
            ref = match.group(1)
            if ':' in ref:
                sec, k = ref.split(':', 1)
            else:
                sec = section_name
                k = ref
            k = k.lower()
            # Check if this is a cycle
            if (sec, k) in seen:
                raise ValueError(f"Circular reference in section '{section_name}' for key '{k}'")
            # Get the value
            if sec == 'DEFAULT':
                if k not in default_keys:
                    raise KeyError(f"Key '{k}' not found in DEFAULT section")
                val = default_keys[k]
            elif sec not in sections:
                raise KeyError(f"Section '{sec}' not found for reference '${ref}'")
            elif k not in sections[sec]:
                raise KeyError(f"Key '{k}' not found in section '{sec}'")
            else:
                val = sections[sec][k]
            # Recursive interpolation
            seen.append((sec, k))
            try:
                return interpolate_value(val, section_name, seen)
            finally:
                seen.pop()

        # Replace all occurrences
        pattern = r'\$\{([^}]+)\}'
        return re.sub(pattern, replace_match, value)

    # Process default keys
    processed_sections = {}
    for sec_name, sec_dict in sections.items():
        if sec_name == 'DEFAULT':
            default_keys = sec_dict.copy()
        else:
            processed_sections[sec_name] = {}
            # First process all keys
            for key, value in sec_dict.items():
                processed_sections[sec_name][key] = interpolate_value(value, sec_name)

    # Apply default keys to sections
    # For each section that doesn't have a key, inherit from DEFAULT if needed
    final_sections = {}
    for sec_name, sec_dict in processed_sections.items():
        final_sections[sec_name] = {}
        # Add all default values where missing in current section
        for key, val in default_keys.items():
            if key not in sec_dict:
                sec_dict[key] = val

        # Apply interpolation to any remaining default values
        for key, val in sec_dict.items():
            final_sections[sec_name][key] = interpolate_value(val, sec_name)

    return final_sections
