import collections
import time

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = {}
        self.access_order = collections.OrderedDict()
        self.stats_ = {"hits": 0, "misses": 0, "evictions": 0, "expirations": 0}

    def _cleanup_expired(self):
        now = self.clock()
        expired_keys = []
        for key, (value, expiry) in self.cache.items():
            if now >= expiry:
                expired_keys.append(key)
        for key in expired_keys:
            del self.cache[key]
            self.access_order.pop(key, None)
            self.stats_["expirations"] += 1

    def _evict_lru(self):
        if not self.access_order:
            return
        lru_key = next(iter(self.access_order))
        del self.cache[lru_key]
        self.access_order.pop(lru_key)
        self.stats_["evictions"] += 1

    def put(self, key, value):
        if self.capacity == 0:
            return

        now = self.clock()
        expiry = now + self.ttl

        # Clean up expired entries first
        self._cleanup_expired()

        # If key already exists, update it (refresh expiry and recency)
        if key in self.cache:
            self.cache[key] = (value, expiry)
            self.access_order.move_to_end(key)
            return

        # If cache is full, evict LRU
        if len(self.cache) >= self.capacity:
            self._evict_lru()

        # Add new entry
        self.cache[key] = (value, expiry)
        self.access_order[key] = None

    def get(self, key, default=None):
        if self.capacity == 0:
            self.stats_["misses"] += 1
            return default

        now = self.clock()

        # Check if key exists
        if key not in self.cache:
            self.stats_["misses"] += 1
            return default

        value, expiry = self.cache[key]

        # Check if expired
        if now >= expiry:
            del self.cache[key]
            self.access_order.pop(key, None)
            self.stats_["expirations"] += 1
            self.stats_["misses"] += 1
            return default

        # Hit: update recency
        self.access_order.move_to_end(key)
        self.stats_["hits"] += 1
        return value

    def __len__(self):
        if self.capacity == 0:
            return 0

        now = self.clock()
        count = 0
        for _, (value, expiry) in self.cache.items():
            if now < expiry:
                count += 1
        return count

    def stats(self):
        return self.stats_.copy()
